   private static void roundTripCheck(final int x, final int z, final ClientboundLevelChunkPacketData sent, final LevelChunk chunk) {
      LevelChunkSection[] sections = chunk.getSections();
      int diff;
      try {
         diff = sent.firstDifference(new ClientboundLevelChunkPacketData(chunk));
      } catch (RuntimeException e) {
         System.out.println("[DEBUG-chunk-rt][client] chunk=" + x + "," + z + " re-encode threw " + e);
         return;
      }
      StringBuilder countDiffs = new StringBuilder();
      for (int i = 0; i < sections.length; i++) {
         LevelChunkSection section = sections[i];
         boolean airBefore = section.hasOnlyAir();
         int[] recount = new int[1];
         section.getStates().count((state, count) -> {
            if (!state.isAir()) {
               recount[0] += count;
            }
         });
         int sentCount = section.sentNonEmptyBlockCount();
         if (recount[0] != sentCount || airBefore != (recount[0] == 0)) {
            countDiffs.append(" s").append(i).append(':').append(sentCount).append("!=").append(recount[0])
               .append("@bits").append(section.getStates().bitsPerEntry());
         }
      }
      if (diff < 0 && countDiffs.length() == 0) {
         System.out.println("[DEBUG-chunk-rt][client] chunk=" + x + "," + z + " OK");
         return;
      }
      String where = "";
      if (diff >= 0) {
         int offset = 0;
         for (int i = 0; i < sections.length; i++) {
            int size = sections[i].getSerializedSize();
            if (diff < offset + size) {
               where = " section=" + i + " sectionOffset=" + (diff - offset) + " bits=" + sections[i].getStates().bitsPerEntry();
               break;
            }
            offset += size;
         }
      }
      System.out.println("[DEBUG-chunk-rt][client] MISMATCH chunk=" + x + "," + z + " byte=" + diff + "/" + sent.payloadLength()
         + where + " counts:" + countDiffs);
   }

